def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to separate build metadata
        parts = version.split('+')
        version_part = parts[0]

        # Split by '-' to separate prerelease
        if '-' in version_part:
            base, prerelease = version_part.split('-', 1)
        else:
            base = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        base_parts = base.split('.')
        major = int(base_parts[0])
        minor = int(base_parts[1])
        patch = int(base_parts[2])

        # Parse prerelease identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert to comparable format
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
        else:
            parsed_prerelease = None

        return (major, minor, patch, prerelease_identifiers if prerelease else [], parsed_prerelease)

    def compare_key(item):
        version_str, index = item
        major, minor, patch, prerelease_ids, parsed_prerelease = parse_version(version_str)

        # For sorting: (major, minor, patch, has_prerelease, prerelease_data, original_index)
        # has_prerelease: 0 if has prerelease (sorts earlier), 1 if no prerelease
        has_prerelease = 0 if parsed_prerelease is not None else 1

        if parsed_prerelease is not None:
            prerelease_key = tuple(parsed_prerelease)
        else:
            prerelease_key = ()

        return (major, minor, patch, has_prerelease, prerelease_key, index)

    # Create list of (version, original_index) pairs
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    # Sort using the comparison key
    sorted_versions = sorted(indexed_versions, key=compare_key)

    # Extract just the version strings
    return [v for v, _ in sorted_versions]

